using Dapper;
using Microsoft.AspNetCore.Mvc;
using Sanadi.Api.Security;
using Sanadi.Application.Security;
using Sanadi.Domain.Exceptions;
using Sanadi.Infrastructure.Persistence;

namespace Sanadi.Api.Controllers;

[ApiController,Route("api/exceptions")]
public sealed class ExceptionsController(ISqlConnectionFactory sql,IPermissionService permissions):ControllerBase
{
    public sealed class TestBody{public string Scenario{get;set;}="";public string Language{get;set;}="en";}
    [HttpGet("log")]
    public async Task<object> Log([FromQuery]int days=14,CancellationToken ct=default){await Require(ct);days=Math.Clamp(days,1,90);await using var conn=sql.Create();var rows=(await conn.QueryAsync<Row>(DbProc.Call("usp_Exceptions_ListLog", new{days}, ct))).ToArray();return new{rows=rows.Select(x=>new{id=x.Id,code=x.Code,label=Label(x.Code),severity=x.Severity,recovered=x.Recovered,escalated=x.Escalated,recoveryAction=x.RecoveryAction,traceId=x.TraceId,caseId=x.CaseId,createdAt=x.CreatedAt}),summary=Summary(rows),windowDays=days};}
    [HttpGet("evidence")]
    public async Task<object> Evidence(CancellationToken ct){await Require(ct);await using var conn=sql.Create();var rows=(await conn.QueryAsync<EvidenceRow>(DbProc.Call("usp_Exceptions_ListEvidence", null, ct))).ToArray();var recovered=rows.Count(x=>x.Recovered);var tests=rows.Where(x=>x.IsTest).Take(12).Select(x=>new{id=x.Id,scenario=x.Scenario??x.Code,label=ScenarioLabel(x.Scenario??x.Code),code=x.Code,recovered=x.Recovered,escalated=x.Escalated,recoveryAction=x.RecoveryAction,studentMessage=x.StudentMessage,traceId=x.TraceId,createdAt=x.CreatedAt,resolvedAt=x.ResolvedAt});return new{detected=rows.Length,recovered,escalated=rows.Count(x=>x.Escalated),recoveryRate=rows.Length==0?0:(int)Math.Round(recovered*100d/rows.Length),realIncidents=rows.Count(x=>!x.IsTest),controlledTests=rows.Count(x=>x.IsTest),latestTests=tests,byCode=Summary(rows)};}
    [HttpPost("test")]
    public async Task<object> Test([FromBody]TestBody b,CancellationToken ct){var actor=await Require(ct);if(!new[]{"ambiguous_request","api_timeout","staff_unavailable","missing_knowledge"}.Contains(b.Scenario)||b.Language is not("en" or "ar"))throw new SanadiException("Invalid exception scenario.");var spec=Spec(b.Scenario,b.Language);var trace=$"exc-{Guid.NewGuid():N}";await using var conn=sql.Create();var id=await conn.ExecuteScalarAsync<Guid>(DbProc.Call("usp_Exceptions_InsertTest", new{spec.code,actor,detail=$"Controlled test: {b.Scenario}",spec.action,spec.escalated,trace,spec.message,scenario=b.Scenario}, ct));return new{scenario=b.Scenario,label=ScenarioLabel(b.Scenario),spec.code,detected=true,recovered=true,spec.escalated,recoveryAction=spec.action,studentMessage=spec.message,traceId=trace,pass=true,note=spec.note,id};}
    // Align with Monitoring page gate (can_monitor_cases), not the stricter all-units check.
    private async Task<Guid> Require(CancellationToken ct){var u=HttpContext.GetSanadiUser();if(!u.IsAuthenticated||u.UserId is not Guid id)throw new UnauthorizedException();if(!await permissions.CanMonitorCasesAsync(id,ct))throw new ForbiddenException();return id;}
    private static object[] Summary(IEnumerable<RowBase> rows)=>rows.GroupBy(x=>x.Code).Select(g=>new{code=g.Key,label=Label(g.Key),total=g.Count(),recovered=g.Count(x=>x.Recovered),escalated=g.Count(x=>x.Escalated)}).OrderByDescending(x=>x.total).Cast<object>().ToArray();
    private static object Label(string c)=>new{en=c switch{"ambiguous_intent"=>"Request not clear enough","api_failure"=>"External service not responding","staff_unavailable"=>"No staff member available","missing_knowledge"=>"No approved document found",_=>c.Replace('_',' ')},ar=c.Replace('_',' ')};
    private static object ScenarioLabel(string c)=>new{en=c switch{"ambiguous_request"=>"Ambiguous request","api_timeout"=>"Simulated service timeout","staff_unavailable"=>"Staff unavailable","missing_knowledge"=>"Missing knowledge",_=>c},ar=c.Replace('_',' ')};
    private static (string code,string action,bool escalated,string message,object note) Spec(string s,string lang)=>s switch{"ambiguous_request"=>("ambiguous_intent","ask_clarification",false,lang=="ar"?"أريد أن أفهم طلبك بدقة — هل يمكنك توضيح ما تحتاجه في سطر واحد؟":"I want to get this right — could you tell me in one line what you need?",new{en="The vague request was detected and answered with one focused clarification question.",ar="تم اكتشاف الطلب الغامض والرد بسؤال توضيحي واحد."}),"api_timeout"=>("api_failure","retry_then_verified_fallback",false,"",new{en="The call was retried once and then served from verified data; the student saw no technical error.",ar="أُعيدت المحاولة مرة ثم استُخدمت بيانات موثقة."}),"staff_unavailable"=>("staff_unavailable","unit_queue_with_admin_attention",true,lang=="ar"?"طلبك لدى الوحدة المسؤولة وسيتم تحديد الموظف المسؤول قريباً.":"Your request is with the responsible unit and someone will be named shortly.",new{en="Work was placed in the unit queue and flagged for admin attention.",ar="وُضع العمل في قائمة انتظار الوحدة مع تنبيه الإدارة."}),_=>("missing_knowledge","safe_no_answer_with_human_handoff_offer",false,lang=="ar"?"لا يوجد لديّ مستند جامعي معتمد يجيب على هذا حتى الآن.":"I do not have an approved university document that answers this yet.",new{en="No approved source covered the probe, so no answer was invented.",ar="لم يغط مصدر معتمد السؤال، لذلك لم تُختلق إجابة."})};
    private class RowBase{public string Code{get;init;}="";public bool Recovered{get;init;}public bool Escalated{get;init;}}
    private sealed class Row:RowBase{public Guid Id{get;init;}public string Severity{get;init;}="warning";public string? RecoveryAction{get;init;}public string? TraceId{get;init;}public Guid? CaseId{get;init;}public DateTimeOffset CreatedAt{get;init;}}
    private sealed class EvidenceRow:RowBase{public Guid Id{get;init;}public string? RecoveryAction{get;init;}public string? TraceId{get;init;}public DateTimeOffset CreatedAt{get;init;}public DateTimeOffset? ResolvedAt{get;init;}public string? StudentMessage{get;init;}public bool IsTest{get;init;}public string? Scenario{get;init;}}
}
